// caWait reports whether a future resolved within the bound.
func caWait(f Future, wait time.Duration) error {
	ch := make(chan error, 1)
	go func() { ch <- f.Error() }()
	select {
	case err := <-ch:
		return err
	case <-time.After(wait):
		return fmt.Errorf("future did not resolve")
	}
}

