			confirmed++
			lastConfirmedMs = elapsed
			if peer != nil {
				confirmedAfterLeader++
				if c := peer.getCommitIndex(); c > leader.getLastApplied() {
					commitAheadWhileConfirming = true
					peerCommitIndex = c
					leaderAppliedAtCommitAhead = leader.getLastApplied()
					if commitAheadMs < 0 {
						commitAheadMs = elapsed
					}
				}
			}
		}
