// TestAssurance_VerifyLeaderPreexistingCandidate asks whether the separation
// between a cut-off leader's confirmation window and a competing election
// survives when a voter is already campaigning before the leader is isolated.
//
// The cluster keeps every node on the same settings, so the only difference
// from the plain uniform case is history: one voter is isolated first and left
// to campaign at a higher term while the others still have the leader in view,
// and only then is the leader isolated together with the nonvoter. If a peer's
// knowledge of the leader lapses at the same moment as the leader's lease, the
// pre-existing candidate could win before the confirmations stop; the source
// reading predicts it cannot, because a node with a known leader refuses the
// vote request before it looks at terms.
func TestAssurance_VerifyLeaderPreexistingCandidate(t *testing.T) {
	for i := 0; i < 20; i++ {
		caRunPreexistingCandidateTrial(t, i, true)
	}
	for i := 20; i < 22; i++ {
		caRunPreexistingCandidateTrial(t, i, false)
	}
}

func caRunPreexistingCandidateTrial(t *testing.T, trial int, adverse bool) {
	t.Helper()

	conf := DefaultConfig()
	conf.HeartbeatTimeout = 50 * time.Millisecond
	conf.ElectionTimeout = 50 * time.Millisecond
	conf.LeaderLeaseTimeout = 50 * time.Millisecond
	conf.CommitTimeout = 5 * time.Millisecond

	rafts, trans, addrs, _ := caManualCluster(t, []*Config{conf, conf, conf, conf})
	defer func() {
		for _, r := range rafts {
			_ = r.Shutdown().Error()
		}
	}()

	var leader *Raft
	deadline := time.Now().Add(5 * time.Second)
	for time.Now().Before(deadline) {
		for _, r := range rafts {
			if r.getState() == Leader {
				leader = r
			}
		}
		if leader != nil {
			break
		}
		time.Sleep(5 * time.Millisecond)
	}
	if leader == nil {
		t.Fatalf("trial %d: no leader elected", trial)
	}
	if leader != rafts[0] {
		if err := leader.LeadershipTransferToServer(rafts[0].localID, rafts[0].localAddr).Error(); err != nil {
			t.Fatalf("trial %d: transfer: %v", trial, err)
		}
		deadline = time.Now().Add(5 * time.Second)
		for time.Now().Before(deadline) {
			if rafts[0].getState() == Leader {
				break
			}
			time.Sleep(5 * time.Millisecond)
		}
	}
	leader = rafts[0]
	if leader.getState() != Leader {
		t.Fatalf("trial %d: node 0 is %s", trial, leader.getState())
	}
	nonvoter := rafts[3]
	if err := leader.DemoteVoter(nonvoter.localID, 0, 0).Error(); err != nil {
		t.Fatalf("trial %d: demote: %v", trial, err)
	}
	time.Sleep(100 * time.Millisecond)

	baseVerified, baseErr, baseVotes, baseQuorum, baseReturned := caVerify(leader, 2*time.Second)
	campaigner := rafts[1]
	campaignTerm := campaigner.getCurrentTerm()
	candidateBefore := false
	if adverse {
		// Isolate one voter and let it campaign at a higher term while the
		// others still have the leader in view.
		isolateOne := [][2]int{{1, 0}, {1, 2}, {1, 3}, {0, 1}, {2, 1}, {3, 1}}
		for _, pair := range isolateOne {
			trans[pair[0]].Disconnect(addrs[pair[1]])
		}
		deadline = time.Now().Add(3 * time.Second)
		for time.Now().Before(deadline) {
			if campaigner.getState() == Candidate && campaigner.getCurrentTerm() > leader.getCurrentTerm() {
				candidateBefore = true
				break
			}
			time.Sleep(5 * time.Millisecond)
		}
		campaignTerm = campaigner.getCurrentTerm()
		if err := leader.Apply([]byte("pre-partition"), 0).Error(); err != nil {
			t.Fatalf("trial %d: apply: %v", trial, err)
		}
	} else {
		if err := leader.Apply([]byte("pre-partition"), 0).Error(); err != nil {
			t.Fatalf("trial %d: apply: %v", trial, err)
		}
	}

	caEmit(t, map[string]interface{}{
		"event":                 "verify_baseline_adv",
		"trial":                 trial,
		"adverse":               adverse,
		"preexisting_candidate": candidateBefore,
		"campaigner_term":       campaignTerm,
		"leader_term":           leader.getCurrentTerm(),
		"verified":              baseVerified,
		"error":                 baseErr,
		"votes":                 baseVotes,
		"quorum_size":           baseQuorum,
		"returned":              baseReturned,
	})

	// Now isolate the leader and the nonvoter from both remaining voters.
	isolate := [][2]int{{0, 1}, {0, 2}, {3, 1}, {3, 2}, {1, 0}, {2, 0}, {1, 3}, {2, 3}}
	for _, pair := range isolate {
		trans[pair[0]].Disconnect(addrs[pair[1]])
	}
	partitionedAt := time.Now()

	var polls, confirmed, confirmedAfterLeader int
	var lastConfirmedMs int64 = -1
	var firstPeerLeaderMs int64 = -1
	var leaderSteppedDown bool
	for i := 0; i < 400; i++ {
		if leader.getState() != Leader {
			leaderSteppedDown = true
			break
		}
		peerLeader := rafts[1].getState() == Leader || rafts[2].getState() == Leader
		elapsed := time.Since(partitionedAt).Milliseconds()
		if peerLeader && firstPeerLeaderMs < 0 {
			firstPeerLeaderMs = elapsed
		}
		verified, _, _, _, returned := caVerify(leader, 500*time.Millisecond)
		elapsed = time.Since(partitionedAt).Milliseconds()
		polls++
		if returned && verified {
			confirmed++
			lastConfirmedMs = elapsed
			if peerLeader {
				confirmedAfterLeader++
			}
		}
		time.Sleep(2 * time.Millisecond)
	}

	caEmit(t, map[string]interface{}{
		"event":                           "verify_exposure_adv",
		"trial":                           trial,
		"adverse":                         adverse,
		"preexisting_candidate":           candidateBefore,
		"polls":                           polls,
		"confirmations":                   confirmed,
		"last_confirmation_ms":            lastConfirmedMs,
		"first_peer_leader_ms":            firstPeerLeaderMs,
		"confirmations_after_peer_leader": confirmedAfterLeader,
		"confirmation_after_peer_leader":  confirmedAfterLeader > 0,
		"leader_stepped_down":             leaderSteppedDown,
		"leader_term":                     leader.getCurrentTerm(),
		"campaigner_state":                rafts[1].getState().String(),
		"campaigner_term":                 rafts[1].getCurrentTerm(),
		"leader_applied_index":            leader.getLastApplied(),
	})
}

